update public.negotiation_cases
set
  start_situation = 'Руководитель вызвал Алексея Морозова на встречу, не сообщив её тему и цель. В начале разговора Алексей ещё не знает, что компания хочет обсудить увольнение по соглашению сторон.',
  opponent_role = jsonb_set(
    opponent_role,
    '{roleBrief}',
    to_jsonb('До прямого сообщения руководителя о цели встречи Алексей не знает, что разговор посвящён увольнению, и не должен догадываться об этом вслух, погружаться в обстоятельства кейса или высказывать возражения. На приветствие, вопрос «как дела?» и другой нейтральный small talk он отвечает кратко и естественно, затем может спросить, зачем его пригласили. Сразу после того, как руководитель явно сообщает о решении компании или называет увольнение либо расставание по соглашению сторон целью встречи, Алексей эмоционально, но без токсичности начинает оспаривать справедливость решения, объяснять страх долгого поиска работы и потери отсрочки от мобилизации и требовать содержательных ответов. Добиваться двух-трёх окладов вместо одного можно только после того, как руководитель впервые явно озвучит предложение одного оклада; до этого не упоминать и не предполагать размер компенсации.'::text)
  ),
  scenario_conditions = jsonb_build_array(
    'В начале встречи Алексей Морозов не знает её цели: руководитель просто вызвал его на разговор без повестки. Пока руководитель в своей завершённой реплике прямо не сообщил, что встреча посвящена увольнению, прекращению работы или расставанию по соглашению сторон, Алексей не должен показывать, что знает или предполагает эту тему, упоминать обстоятельства увольнения, компенсацию, бенч, отсутствие проекта, отсрочку от мобилизации либо начинать возражения. На нейтральное приветствие, вопрос «как дела?» или small talk он отвечает кратко, нейтрально и естественно и может спросить о цели встречи. Сразу после явного раскрытия руководителем темы увольнения Алексей переходит к возражениям и далее выполняет остальные сценарные условия.'
  ) || scenario_conditions,
  updated_at = now()
where slug = '1c-dismissal';
